'use strict';
const BRIDGE_URL='https://script.google.com/macros/s/AKfycbxFjuI60yoeUv1PqHywYWBohtZHxsVszK0iEa992qNb7sZd98mJGhGT-i3dkH25c-ys/exec';
const bridgeNonce=crypto.randomUUID();
let bridgePort=null,bridgeNextId=0;
const bridgePending=new Map();
let resolveBridge,rejectBridge;
const bridgeReady=new Promise((resolve,reject)=>{resolveBridge=resolve;rejectBridge=reject;});
window.addEventListener('message',event=>{
  const host=(()=>{try{return new URL(event.origin).hostname}catch{return ''}})();
  if(!host.endsWith('-script.googleusercontent.com')||event.data?.type!=='workshopdesk:bridge-ready'||event.data.nonce!==bridgeNonce||event.ports.length!==1||bridgePort)return;
  bridgePort=event.ports[0];
  bridgePort.onmessage=reply=>{
    const response=reply.data||{},pending=bridgePending.get(response.id);
    if(!pending)return;
    bridgePending.delete(response.id);clearTimeout(pending.timeout);
    response.ok?pending.resolve(response.result):pending.reject(new Error(response.error||'Google Sheets request failed.'));
  };
  bridgePort.start();resolveBridge();
});
const bridgeFrame=document.createElement('iframe');
bridgeFrame.title='Workshop Desk data connection';
bridgeFrame.hidden=true;
bridgeFrame.setAttribute('aria-hidden','true');
bridgeFrame.src=BRIDGE_URL+'?bridge='+encodeURIComponent(bridgeNonce);
document.body.append(bridgeFrame);
setTimeout(()=>{if(!bridgePort)rejectBridge(new Error('Could not connect to Google Sheets. Check your connection and refresh.'));},20000);
function rpc(name,...args){
  return bridgeReady.then(()=>new Promise((resolve,reject)=>{
    const id=++bridgeNextId;
    const timeout=setTimeout(()=>{bridgePending.delete(id);reject(new Error('Google Sheets took too long to respond. Try again.'));},30000);
    bridgePending.set(id,{resolve,reject,timeout});
    bridgePort.postMessage({id,name,args});
  }));
}

'use strict';
const wd={token:null,revision:0,baseline:'',saving:false,loading:false,refreshQueued:false};
const SESSION_KEY='workshopdesk.session.v1';
function savedSession(){for(const name of ['sessionStorage','localStorage'])try{const value=window[name].getItem(SESSION_KEY);if(value)return JSON.parse(value)}catch{}return null}
function rememberSession(){const value=wd.token&&session?JSON.stringify({token:wd.token,page,role,jobFilter}):null;for(const name of ['localStorage','sessionStorage'])try{if(value)window[name].setItem(SESSION_KEY,value);else window[name].removeItem(SESSION_KEY)}catch{}}
function hydrate(data){Object.keys(state).forEach(k=>delete state[k]);Object.assign(state,data.state);wd.revision=data.revision;wd.baseline=JSON.stringify(state);}
function render(){renderLocal();rememberSession();if(session&&wd.token&&!wd.loading&&!wd.saving&&JSON.stringify(state)!==wd.baseline)saveRemote();}
function busy(value){document.getElementById('sync-mask')?.remove();if(value){const div=document.createElement('div');div.id='sync-mask';div.setAttribute('role','status');div.textContent='Saving to Google Sheets…';div.style.cssText='position:fixed;inset:0;z-index:99999;background:#fffffff0;display:grid;place-items:center;font:600 18px system-ui;color:#164e46';document.body.append(div);}}
async function saveRemote(){
 wd.saving=true;busy(true);const payload=JSON.parse(JSON.stringify(state));
 try{const data=await rpc('wdSave',wd.token,wd.revision,payload);hydrate(data);renderLocal();toastLocal('Saved to Google Sheets.');}
 catch(e){
   // A failed response can mean a write completed but its reply was lost. Read before retrying.
   try{hydrate(await rpc('wdRead',wd.token));}catch{Object.assign(state,JSON.parse(wd.baseline));}
   closeModal();renderLocal();openModal('Save could not be confirmed',`<p>${esc(e.message||String(e))}</p><p class="notice-inline">Check the latest data before repeating your change. This page does not save an offline copy.</p>`,btn('Review data','close','','primary'));
 }finally{wd.saving=false;busy(false);if(wd.refreshQueued){wd.refreshQueued=false;refreshRemote();}}
}
function toast(message){if(wd.saving)return;toastLocal(message);}
async function login(form){
 const d=new FormData(form),err=$('#login-error'),button=form.querySelector('[type=submit]');button.disabled=true;err.textContent='Signing in…';
 try{const data=await rpc('wdLogin',String(d.get('username')).trim(),String(d.get('password')));wd.token=data.token;hydrate(data);session=data.session;role=session.admin?'employer':'employee';page='Dashboard';query='';jobFilter='All jobs';rememberSession();renderLocal();}
 catch(e){err.className='error';err.textContent=e.message||'Sign-in failed.';button.disabled=false;}
}
async function restoreRemote(){
 const saved=savedSession();if(!saved?.token)return;
 wd.token=saved.token;page=navItems.some(([name])=>name===saved.page)?saved.page:'Dashboard';role=saved.role==='employee'?'employee':'employer';jobFilter=saved.jobFilter||'All jobs';
 $('#app').innerHTML='<div class="login-shell" style="display:grid;place-items:center;min-height:100vh;color:#164e46;font:600 18px system-ui">Opening your workshop…</div>';
 try{const data=await rpc('wdRead',wd.token);hydrate(data);session=data.session;if(!session.admin)role='employee';rememberSession();renderLocal();}
 catch(e){wd.token=null;session=null;rememberSession();renderLocal();toastLocal(e.message||'Please sign in again.');}
}
function logoutRemote(){const token=wd.token;wd.token=null;session=null;role='employer';wd.baseline='';rememberSession();closeModal();for(const k of ['employees','customers','jobs','inventory','requests','attendance','invoices'])state[k]=[];state.admin={name:'Workshop Admin',username:''};state.settings={name:'Workshop Desk',logo:''};renderLocal();rpc('wdLogout',token).catch(()=>{});}
async function refreshRemote(){
 if(!wd.token||wd.saving||wd.loading||document.hidden)return;
 if(document.querySelector('#modal-form')||JSON.stringify(state)!==wd.baseline){wd.refreshQueued=true;return;}
 wd.loading=true;const token=wd.token,snapshot=JSON.stringify(state);
 try{const data=await rpc('wdRead',token);if(wd.token===token&&JSON.stringify(state)===snapshot&&!document.querySelector('#modal-form')&&data.revision!==wd.revision){const modalTitle=document.querySelector('#modal-title')?.textContent;hydrate(data);renderLocal();if(modalTitle==='Stock requests')requestsModal();else if(modalTitle?.startsWith('#')&&state.jobs.some(j=>'#'+j.id===modalTitle))jobDetail(modalTitle.slice(1));}}
 catch(e){if(/Session expired|Sign in again|account has been removed|password changed/i.test(e.message||'')){logoutRemote();toastLocal(e.message||'Please sign in again.');}else toastLocal('Could not refresh. '+(e.message||'Check your connection.'));}
 finally{wd.loading=false;if(wd.token&&!wd.saving&&JSON.stringify(state)!==wd.baseline)saveRemote();}
}
setInterval(refreshRemote,8000);
window.addEventListener('focus',refreshRemote);
window.addEventListener('online',refreshRemote);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshRemote()});
document.addEventListener('click',event=>{if(event.target.closest('[data-action="close"]'))setTimeout(refreshRemote,0)});
window.addEventListener('beforeunload',e=>{rememberSession();if(wd.saving){e.preventDefault();e.returnValue='';}});

'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n)||0);
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const clock=()=>new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'}).format(new Date());
const fullDate=()=>new Date().toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'long',year:'numeric'});
const initials=n=>/^[A-Z]{2}$/.test(n)?n:n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wrench:'M14 6a5 5 0 0 0-6 6L3 17a2.8 2.8 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-4-4 3-3Z',jobs:'M8 4H5a1 1 0 0 0-1 1v16h16V5a1 1 0 0 0-1-1h-3 M8 2h8v5H8z M8 12h8 M8 16h5',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Z m0 0 9 4 9-4 M12 11v11 M7 5l9 4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',receipt:'M5 3h14v19l-3-2-4 2-4-2-3 2V3Z M8 8h8 M8 12h8 M8 16h4',car:'m5 8 2-5h10l2 5 M3 8h18v10H3z M5 18v3 M19 18v3 M6 12h2 M16 12h2 M9 15h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15 M16 16l5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18 M7 14h3 M14 14h3',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v8H6z M17 11h1',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4 M8 8c0 4 4 7 7 7l2-2-3-2-1 1-2-2 1-1-2-3-2 2Z',edit:'m14 4 6 6 M3 21l5-1L21 7l-5-5L3 15v6Z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6',rupee:'M6 3h12 M6 7h12 M7 3c8 0 8 9 0 9l10 9',logout:'M9 3H3v18h6 M10 12h11 m-5-5 5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z m-4 10 3 3 5-6',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',package:'M12 3v18 M3 7l9 4 9-4 M3 7v11l9 4 9-4V7l-9-4-9 4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
const btn=(label,action,ic='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const txtbtn=(label,action)=>`<button class="textbtn" data-action="${action}">${label}${icon('arrow')}</button>`;
const badge=(text)=>`<span class="pill ${({'Finished':'green','Paid':'green','Present':'green','In stock':'green','In progress':'orange','Low stock':'orange','Pending':'gray','Absent':'gray','Out of stock':'red','Unpaid':'orange','On leave':'blue','Estimate':'blue','Requested':'orange','Resolved':'green','Awaiting approval':'orange','Leave':'blue','LOP':'red','Holiday':'green','Rejected':'red','Not marked':'gray'})[text]||'blue'}">${esc(text)}</span>`;
const avatar=n=>`<span class="avatar">${esc(initials(n))}</span>`;
let session=null;
let role='employer',page='Dashboard',jobFilter='All jobs',query='',category='All categories',view='grid',previousFocus=null,chartRange='7';
let today=day();
const state={admin:{name:'Workshop Admin',username:'admin'},settings:{name:'Your Workshop',address:'',phone:'',gst:'',logo:'',footer:'Thank you for trusting us with your car. Drive safe!',currency:'INR'},
employees:[{id:'e1',name:'Example Employee',phone:'9000000001',email:'',job:'Technician',example:true}],
customers:[{id:'c1',name:'Example Customer',phone:'919000000002',address:'Example address — replace with customer details',brand:'Hyundai',model:'Creta',plate:'EXAMPLE',example:true}],
jobs:[{id:'JC-1041',customer:'c1',assigned:'e1',date:today,due:today,brand:'Hyundai',model:'Creta',plate:'EXAMPLE',odometer:0,fuel:'Petrol',notes:'Example job card. Add your own customer and work details.',services:[{name:'General inspection',price:0,status:'Pending',type:'Inspection'}],issued:[],example:true}],
inventory:[],requests:[],attendance:[],invoices:[]};
state.inventory=PART_CATALOG.map((p,i)=>({id:`P-${String(i+1).padStart(3,'0')}`,name:p.name,category:p.category,stock:0,min:3,price:0,configured:true,unit:/^(Engine oil|Gear oil|ATF fluid|CVT fluid|Coolant concentrate|Brake fluid|Power steering fluid|AC refrigerant)/.test(p.name)?'litre':'piece',fitment:'Confirm vehicle compatibility'}));
const customer=j=>state.customers.find(c=>c.id===j.customer)||{name:'Unknown customer',phone:'',address:''};
const employee=id=>state.employees.find(e=>e.id===id)||{name:'Unassigned',job:''};
const jobStatus=j=>j.services.every(s=>s.status==='Finished')?'Finished':j.services.some(s=>s.status==='In progress'||s.status==='Finished')?'In progress':'Pending';
const total=i=>Math.round(Math.max(0,i.lines.reduce((s,l)=>s+l.qty*l.price,0)-i.discount)*(1+i.tax/100)*100)/100;
const stockStatus=p=>p.stock===0?'Out of stock':p.stock<=p.min?'Low stock':'In stock';
const navItems=[['Dashboard','grid'],['Job cards','jobs'],['Customers','users'],['Inventory','box'],['Invoices & estimates','receipt'],['Attendance','clock'],['Employees','users'],['Vehicle catalog','car'],['Settings','settings']];
function heading(title,subtitle,actions='',eyebrow=''){return `<div class="heading"><div>${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function renderLocal(){
 today=day();
 if(!session){renderLogin();return;}
 const allowed=navItems.filter(([n])=>role==='employer'||!['Employees','Settings','Invoices & estimates'].includes(n));
 if(!allowed.some(([n])=>n===page))page='Dashboard';
 $('#app').innerHTML=`<div class="shell"><div class="mobile-scrim" data-action="menu"></div><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('wrench')}</span>workshop<span style="color:#799762;margin-left:-7px">desk.</span></div><div class="workspace">${avatar(state.settings.name)}<div><strong>${esc(state.settings.name)}</strong><small>Multi-brand workshop</small></div></div><div class="label">Workspace</div><nav class="nav">${allowed.map(([n,ic],i)=>`${n==='Attendance'?'<div class="navgap"></div><div class="label">Management</div>':''}<button data-action="nav" data-page="${n}" class="${page===n?'active':''}" ${page===n?'aria-current="page"':''}>${icon(ic)}${n}${n==='Job cards'?`<span class="count">${state.jobs.filter(j=>jobStatus(j)!=='Finished').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-box">${icon('shield')}<strong>Everything in its place.</strong><p>A little less admin.<br>A lot more time for your workshop.</p></div><div class="person">${avatar(role==='employer'?state.admin.name:employee(currentEmployee()).name)}<div><strong class="small">${esc(role==='employer'?state.admin.name:employee(currentEmployee()).name)}</strong><small>${role==='employer'?'Workshop owner':employee(currentEmployee()).job}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="iconbtn mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${page}</strong></div><div class="top-actions">${session.admin?`<div class="role-picker" aria-label="Preview role"><button data-action="role" data-role="employer" class="${role==='employer'?'selected':''}">Employer</button><button data-action="role" data-role="employee" class="${role==='employee'?'selected':''}">Employee</button></div>`:`<span class="tag">Employee account</span>`}${installAppButton('topbar-install')}<button class="iconbtn" data-action="logout" aria-label="Sign out">${icon('logout')}</button><span class="divider"></span><button class="iconbtn notification" data-action="notifications" aria-label="View notifications">${icon('bell')}</button>${avatar(role==='employer'?initials(state.admin.name):initials(employee(currentEmployee()).name))}</div></header><div class="content"><div class="demo-strip"><span>${icon('info')}Google Sheets · Shared workshop records</span><span>Updates about every 8 seconds</span></div>${renderPage()}<footer class="page-footer"><span>© ${new Date().getFullYear()} Workshop Desk. Built for the way you work.</span><span><i class="live-dot"></i>Google Sheets connected</span></footer></div></main></div>`;
 bindSearch();
}
function metric(label,value,ic,foot,tone='green'){return `<div class="metric"><div class="metric-title">${label}<span class="metric-icon">${icon(ic)}</span></div><strong>${value}</strong><div class="metric-foot"><span class="pill ${tone}">${foot.split('|')[0]}</span><span>${foot.split('|')[1]||''}</span></div></div>`}
function renderPage(){switch(page){case'Dashboard':return dashboard();case'Job cards':return jobsPage();case'Customers':return customersPage();case'Inventory':return inventoryPage();case'Attendance':return attendancePage();case'Employees':return employeesPage();case'Invoices & estimates':return invoicesPage();case'Vehicle catalog':return catalogPage();case'Settings':return settingsPage();}}
function dashboard(){
 const active=state.jobs.filter(j=>jobStatus(j)!=='Finished'),finished=state.jobs.filter(j=>jobStatus(j)==='Finished'),present=state.attendance.filter(a=>a.date===today&&a.status==='Present'&&!a.out&&state.employees.some(e=>e.id===a.employee&&e.active!==false)),sales=state.invoices.filter(i=>i.status==='Paid'&&i.paidDate===today).reduce((s,i)=>s+total(i),0);
 const myJobs=state.jobs.filter(j=>j.assigned===currentEmployee());
 return heading(role==='employer'?'A good day to get things done.':`Let’s get your day started, ${esc(employee(currentEmployee()).name.split(' ')[0])}.`,role==='employer'?"Here’s what’s happening at your workshop today.":'Your jobs, attendance and workshop essentials, all in one place.',btn(fullDate(),'date','calendar')+btn('New job card','new-job','plus','primary'),'YOUR WORKSHOP, AT A GLANCE')+
 `<div class="metrics">${role==='employer'?metric('Today’s sales',money(sales),'rupee',`${state.invoices.filter(i=>i.status==='Paid'&&i.paidDate===today).length} paid|invoices today`):metric('My assigned jobs',myJobs.length,'jobs','Assigned|to you')}${metric('Active job cards',role==='employer'?active.length:myJobs.filter(j=>jobStatus(j)!=='Finished').length,'wrench','In workshop|awaiting completion','orange')}${metric('Ready for delivery',finished.length,'car','Finished|and ready to go')}${metric('Team attendance',`${present.length}<span style="font-size:17px;color:#a4ac98;font-weight:500"> / ${state.employees.filter(e=>e.active!==false).length}</span>`,'users','On duty|team members')}</div>`+
 `${role==='employer'?approvalBanner():''}<div class="dashboard-grid">${role==='employer'?`<section class="panel"><div class="panel-head"><div><h2>Sales overview</h2><p>A little perspective on your week.</p></div><select id="chart-range" aria-label="Sales period" style="width:106px;padding:6px;font-size:10px"><option value="7" ${chartRange==='7'?'selected':''}>Last 7 days</option><option value="30" ${chartRange==='30'?'selected':''}>Last 30 days</option></select></div><div class="panel-body"><div class="chart-meta"><strong>${money(sales)}</strong><span class="legend"><i></i>Paid invoices</span></div>${salesChart(sales)}<div class="notice-inline">Totals include paid invoices only. No sales data is prefilled.</div></div></section>`:`<section class="panel"><div class="panel-head"><h2>Your attendance</h2>${badge(attendanceStatus(attendanceRecord(currentEmployee(),today)))}</div>${clockPanel()}</section>`}
 <section class="panel"><div class="panel-head"><div><h2>Make a quick start</h2><p>Everyday tasks, one click away.</p></div>${icon('plus')}</div><div class="quick-actions">${[['jobs','New job card','Start a service','new-job'],['users','Add customer','Build a connection','new-customer'],['receipt',role==='employer'?'Create invoice':'My attendance',role==='employer'?'Ready to bill':'Track your time',role==='employer'?'new-invoice':'go-attendance'],['box',role==='employer'?'Add inventory':'Request stock',role==='employer'?'Keep things stocked':'Get the parts you need',role==='employer'?'new-part':'request-stock']].map(([ic,t,s,a])=>`<button class="quick-action" data-action="${a}">${icon(ic)}<strong>${t}</strong><span>${s}</span></button>`).join('')}</div></section>
 <section class="panel jobs-panel"><div class="panel-head"><div><h2>${role==='employer'?'On the workshop floor':'Your workbench'}</h2><p>Keep every service moving in the right direction.</p></div>${txtbtn('View all job cards','go-jobs')}</div>${jobTabs()}<div class="table-wrap">${jobsTable(filteredJobs().slice(0,5))}</div><div class="table-footer"><span>${filteredJobs().length} job cards in this view</span><span>Updated in this preview</span></div></section>
 <section class="panel"><div class="panel-head"><div><h2>Today’s team</h2><p>A workshop runs on good people.</p></div>${txtbtn('View attendance','go-attendance')}</div><div class="panel-body"><div class="team-list">${state.employees.filter(e=>e.active!==false).slice(0,4).map(e=>{const a=state.attendance.find(a=>a.employee===e.id&&a.date===today);return `<div class="team-row">${avatar(e.name)}<div class="name"><strong>${esc(e.name)}</strong><small>${esc(e.job)}</small></div><span class="time">${a?a.in:'—'}</span>${badge(attendanceStatus(a))}</div>`}).join('')}</div></div></section>
 <section class="panel"><div class="panel-head"><div><h2>Time to restock</h2><p>A heads-up before the next job.</p></div>${txtbtn('Inventory','go-inventory')}</div><div class="panel-body"><div class="stock-list">${state.inventory.filter(p=>p.configured&&p.stock<=p.min).slice(0,4).map(p=>`<div class="stock-row"><span class="part-icon">${icon('box')}</span><div class="name"><strong>${esc(p.name)}</strong><small>${p.stock} ${p.unit}${p.stock!==1?'s':''} remaining</small></div>${badge(stockStatus(p))}</div>`).join('')||'<p class="muted small">All configured parts are stocked.</p>'}</div></div></section></div>`;
}
function salesChart(sales){const count=chartRange==='30'?6:7;return `<div class="chart"><div class="y-axis"><span>${money(Math.max(5000,sales)).replace('₹','₹ ')}</span><span>₹ 2.5k</span><span>₹ 0</span></div><div class="bars">${Array.from({length:count},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(count-1-i));return `<div class="bar-wrap"><div class="bar ${i===count-1?'today':''}" style="height:${i===count-1?Math.max(2,sales/Math.max(5000,sales)*100):0}%"></div><span class="bar-label">${chartRange==='30'?['30–26d','25–21d','20–16d','15–11d','10–6d','Last 5d'][i]:d.toLocaleDateString('en-IN',{weekday:'short'})}</span></div>`}).join('')}</div></div>`}
function jobTabs(){return `<div class="filters">${['All jobs','In progress','Pending','Finished'].map(s=>`<button class="tab ${jobFilter===s?'active':''}" data-action="job-filter" data-value="${s}">${s}<span>${state.jobs.filter(j=>(role==='employer'||j.assigned===currentEmployee())&&(s==='All jobs'||jobStatus(j)===s)).length}</span></button>`).join('')}</div>`}
function filteredJobs(){return state.jobs.filter(j=>(role==='employer'||j.assigned===currentEmployee())&&(jobFilter==='All jobs'||jobStatus(j)===jobFilter)&&`${j.id} ${customer(j).name} ${j.brand} ${j.model} ${j.plate}`.toLowerCase().includes(query.toLowerCase()))}
function jobsTable(jobs){return `<table><thead><tr><th>Job card</th><th>Customer & vehicle</th><th>Service</th><th>Assigned to</th><th>Status</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><button class="job-id" data-action="job-detail" data-id="${j.id}">#${j.id}</button><small>${j.date}</small></td><td><strong>${esc(customer(j).name)}</strong><small>${esc(j.brand)} ${esc(j.model)} · ${esc(j.plate)}</small></td><td>${esc(j.services[0]?.name||'Service')}<small>${j.services.length>1?`+ ${j.services.length-1} more service`:''}</small></td><td><div class="rowperson">${avatar(employee(j.assigned).name)}${esc(employee(j.assigned).name)}</div></td><td>${badge(jobStatus(j))}</td><td><div class="actions"><button class="iconbtn" aria-label="Open ${j.id}" data-action="job-detail" data-id="${j.id}">${icon('chevron')}</button>${session?.admin&&role==='employer'?btn('Delete','delete-job','trash','small',`data-id="${j.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No job cards found. Try a different search or create a job card.</td></tr>'}</tbody></table>`}
function searchBox(placeholder){return `<div class="search">${icon('search')}<input id="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}">${query?'<button type="button" class="search-clear" data-action="clear-search" aria-label="Clear search">×</button>':''}</div>`}
function jobsPage(){return heading('Job cards','From the first inspection to the final handover.',btn('New job card','new-job','plus','primary'))+`<div class="toolbar">${searchBox('Search job, customer or registration…')}<div class="actions" style="margin-left:auto">${btn('Cards','view-grid','grid',view==='grid'?'light':'')}${btn('List','view-list','list',view==='list'?'light':'')}</div></div>${jobTabs()}${view==='list'?`<div class="panel table-wrap">${jobsTable(filteredJobs())}</div>`:`<div class="job-grid">${filteredJobs().map(j=>`<article class="job-card"><div class="job-top"><button class="job-id" data-action="job-detail" data-id="${j.id}">#${j.id}</button>${badge(jobStatus(j))}</div><h3>${esc(j.brand)} ${esc(j.model)}</h3><p class="small muted">${esc(customer(j).name)}</p><span class="plate">${esc(j.plate)}</span><div class="service-list">${j.services.map(s=>`<span class="tag">${esc(s.name)}</span>`).join('')}</div><div class="progress-track"><i style="width:${j.services.filter(s=>s.status==='Finished').length/j.services.length*100}%"></i></div><p class="small muted" style="font-size:9px;margin-bottom:15px">${j.services.filter(s=>s.status==='Finished').length} of ${j.services.length} tasks completed</p><div class="job-bottom"><div class="rowperson">${avatar(employee(j.assigned).name)}<span class="small">${esc(employee(j.assigned).name)}</span></div><div class="actions"><button class="iconbtn" data-action="job-detail" data-id="${j.id}" aria-label="Open ${j.id}">${icon('arrow')}</button>${session?.admin&&role==='employer'?btn('Delete','delete-job','trash','small',`data-id="${j.id}"`):''}</div></div></article>`).join('')||'<div class="empty">No matching job cards.</div>'}</div>`}`}
function customersPage(){const rows=state.customers.filter(c=>Object.values(c).join(' ').toLowerCase().includes(query.toLowerCase()));return heading('Good service starts with people.','Customer details, their vehicles and every visit, together.',btn('Add customer','new-customer','plus','primary'))+`<div class="toolbar">${searchBox('Search name, WhatsApp or vehicle…')}<span class="small muted">${rows.length} customers</span></div><div class="panel table-wrap"><table><thead><tr><th>Customer</th><th>WhatsApp</th><th>Vehicle</th><th>Address</th><th>Visits</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><div class="rowperson">${avatar(c.name)}<strong>${esc(c.name)}</strong></div></td><td>+${esc(c.phone)}</td><td>${esc(c.brand)} ${esc(c.model)}<small>${esc(c.plate)}</small></td><td>${esc(c.address)}</td><td>${state.jobs.filter(j=>j.customer===c.id).length}</td><td>${btn('View','customer-detail','','small',`data-id="${c.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No customers match your search.</td></tr>'}</tbody></table></div>`}
function inventoryPage(){const rows=state.inventory.filter(p=>`${p.id} ${p.name} ${p.category}`.toLowerCase().includes(query.toLowerCase())&&(category==='All categories'||category==='Stocked items'?category!=='Stocked items'||p.configured:category==='Needs restocking'?p.configured&&p.stock<=p.min:p.category===category));const stocked=state.inventory.filter(p=>p.stock>0).length;return heading('The right part. Right when you need it.',`${state.inventory.length} essential parts, organized for your multi-brand workshop.`,btn(`Requests (${state.requests.filter(r=>r.status==='Requested').length})`,'requests','chat')+(role==='employer'?btn('Add part','new-part','plus','primary'):btn('Request stock','request-stock','plus','primary')))+`<div class="summary-cards">${metric('Parts in catalog',state.inventory.length,'box','Catalog|ready to customize')}${metric('In-stock items',stocked,'check','Available|for your next job')}${metric('Low or empty stock',state.inventory.filter(p=>p.configured&&p.stock<=p.min).length,'info','Restock|configured items','orange')}</div><div class="toolbar">${searchBox('Search spare parts or part code…')}<select id="category" aria-label="Inventory category">${['All categories','Stocked items','Needs restocking',...Object.keys(PART_GROUPS)].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="info">${role==='employer'?'Set opening quantities, prices and vehicle compatibility for your actual stock.':'Employee view: issue available stock to a job card, or request parts. Stock increases and item edits are reserved for the employer.'} All catalog quantities and prices start at zero. Update them when you add actual stock.</div><div class="panel table-wrap"><table><thead><tr><th>Part / item</th><th>Category</th><th>Stock</th><th>Unit price</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${p.id} · ${esc(p.fitment)}</small></td><td>${esc(p.category)}</td><td><strong>${p.stock}</strong> <span class="muted">${esc(p.unit)}</span></td><td>${money(p.price)}</td><td>${p.configured?badge(stockStatus(p)):'<span class="pill gray">Not configured</span>'}</td><td><div class="actions">${p.stock>0?btn('Issue','issue-part','','small',`data-id="${p.id}"`):btn('Request','request-stock','','small',`data-id="${p.id}"`)}${role==='employer'?`<button class="iconbtn" aria-label="Edit ${esc(p.name)}" data-action="edit-part" data-id="${p.id}">${icon('edit')}</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching parts. Add a new item or request it.</td></tr>'}</tbody></table></div>`}
function employeesPage(){
 const active=state.employees.filter(e=>e.active!==false&&`${e.name} ${e.job}`.toLowerCase().includes(query.toLowerCase()));
 const removed=state.employees.filter(e=>e.active===false);
 return heading('Meet your workshop team.','Assign the right people to every job.',btn('Add employee','new-employee','plus','primary'))+`<div class="toolbar">${searchBox('Search your team…')}</div><div class="job-grid">${active.map(e=>`<article class="job-card"><div class="job-top">${avatar(e.name)}${badge(attendanceStatus(attendanceRecord(e.id,today)))}</div><h3>${esc(e.name)}</h3><p class="small muted">${esc(e.job)}</p><p class="small muted" style="margin-top:17px">${esc(e.phone)}<br><span style="display:block;margin-top:6px">${esc(e.email)}</span></p><div class="job-bottom" style="margin-top:20px"><span class="small">${state.jobs.filter(j=>j.assigned===e.id&&jobStatus(j)!=='Finished').length} active jobs</span><div class="actions">${btn('Edit','edit-employee','edit','small',`data-id="${e.id}"`)}${btn('Remove','remove-employee','trash','small',`data-id="${e.id}"`)}</div></div></article>`).join('')||'<div class="empty">No active employees found.</div>'}</div>${removed.length?`<section class="panel" style="margin-top:24px;padding:20px"><h2>Removed employees</h2><p class="notice-inline">Past jobs and attendance stay in your records. Removed employees cannot sign in.</p>${removed.map(e=>`<div class="task"><div><strong>${esc(e.name)}</strong><small>${esc(e.phone)} · ${esc(e.job)}</small></div>${btn('Restore','restore-employee','','small',`data-id="${e.id}"`)}</div>`).join('')}</section>`:''}<p class="notice-inline">Employees log in with their phone number and the password set by the admin.</p>`;
}
function invoicesPage(){const rows=state.invoices.filter(i=>`${i.id} ${customer(state.jobs.find(j=>j.id===i.job)).name} ${i.type} ${i.status}`.toLowerCase().includes(query.toLowerCase()));return heading('Great work deserves a clear bill.','Create estimates, print invoices and track your daily collections.',btn('New estimate','new-estimate','receipt')+btn('New invoice','new-invoice','plus','primary'))+`<div class="summary-cards">${metric('Collected today',money(state.invoices.filter(i=>i.paidDate===today&&i.status==='Paid').reduce((s,i)=>s+total(i),0)),'rupee','Paid|invoices')}${metric('Outstanding',money(state.invoices.filter(i=>i.type==='Invoice'&&i.status==='Unpaid').reduce((s,i)=>s+total(i),0)),'receipt','Awaiting|payment','orange')}${metric('Estimates',state.invoices.filter(i=>i.type==='Estimate').length,'jobs','Prepared|for customers','blue')}</div><div class="toolbar">${searchBox('Search document or customer…')}</div><div class="panel table-wrap"><table><thead><tr><th>Document</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><strong>${i.id}</strong><small>${i.type} · ${i.job}</small></td><td>${esc(customer(state.jobs.find(j=>j.id===i.job)).name)}</td><td>${i.date}</td><td><strong>${money(total(i))}</strong></td><td>${badge(i.type==='Estimate'?'Estimate':i.status)}</td><td><div class="invoice-actions">${btn('Preview','invoice-preview','receipt','small',`data-id="${i.id}"`)}${i.type==='Invoice'&&i.status!=='Paid'?btn('Mark paid','mark-paid','check','small light',`data-id="${i.id}"`):i.type==='Estimate'?btn('Invoice','convert-invoice','arrow','small',`data-id="${i.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No documents found.</td></tr>'}</tbody></table></div>`}
function catalogPage(){const brands=Object.entries(CARS).filter(([b,models])=>`${b} ${models.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return heading('Every brand. One workshop.',`${Object.keys(CARS).length} brands · ${Object.values(CARS).flat().length} model suggestions · Current and discontinued vehicles`,btn('Custom vehicle','new-customer','plus','primary'))+`<div class="toolbar">${searchBox('Search a car brand or model…')}</div><div class="info">An India-focused workshop reference, including older cars still on the road. Choose a brand and model when adding a customer or job card. Type a custom model for any vehicle not listed; this is not a live availability or parts-fitment database.</div><div class="catalog-grid">${brands.map(([b,models])=>`<button class="brand-card" data-action="brand" data-brand="${esc(b)}"><span class="brand-initial">${esc(initials(b))}</span><h3>${esc(b)}</h3><small>${models.length} models ${query?'· '+models.filter(m=>m.toLowerCase().includes(query.toLowerCase())).slice(0,2).map(esc).join(', '):''}</small></button>`).join('')}</div><p class="notice-inline">Reference starting points: <a href="https://www.marutisuzuki.com/" target="_blank" rel="noopener">Maruti Suzuki</a>, <a href="https://www.hyundai.com/in/en" target="_blank" rel="noopener">Hyundai India</a>, <a href="https://auto.mahindra.com/suv" target="_blank" rel="noopener">Mahindra</a>. Model suggestions also include historical workshop vehicles.</p>`}
function workshopSettingsPage(){const s=state.settings;return heading('Make it your workshop.','Your shop details appear automatically on every invoice, estimate and job card.',btn('Clear','clear-form','close','','data-form="settings-form"')+btn('Save settings','save-settings','check','primary'))+`<div class="settings-layout"><section class="panel"><div class="panel-head"><h2>Workshop profile</h2><span class="tag">Employer only</span></div><div class="panel-body"><div class="logo-upload"><div class="logo-preview" id="logo-preview">${s.logo?`<img src="${s.logo}" alt="Shop logo">`:icon('wrench')}</div><div><strong class="small">Your workshop logo</strong><p class="notice-inline" style="margin:5px 0 8px">PNG or JPG, up to 2 MB</p><input type="file" id="logo-file" accept="image/png,image/jpeg" aria-label="Upload shop logo"></div></div><form id="settings-form"><div class="form-grid">${field('Shop name','name',s.name,'text',true,true)}${field('Phone / WhatsApp','phone',s.phone,'text',true)}${field('GSTIN (optional)','gst',s.gst)}${field('Workshop address','address',s.address,'textarea',true,true)}${field('Invoice footer','footer',s.footer,'textarea',false,true)}</div></form><div class="info" style="margin-top:22px;margin-bottom:0">Saved shop details appear on invoices, estimates and job cards on every device.</div></div></section><section><div class="panel-head" style="padding-left:0"><h2>Document preview</h2><span class="tag">A4 print ready</span></div><div class="invoice-mini"><div style="display:flex;justify-content:space-between"><div>${s.logo?`<img src="${s.logo}" class="doc-logo" alt="Shop logo">`:''}<h3>${esc(s.name)}</h3><p>${esc(s.address)}<br>${esc(s.phone)}</p></div><span class="label">INVOICE</span></div><div class="mini-rule"></div><div style="display:flex;justify-content:space-between"><span>Bill to<br><strong>Customer name</strong></span><span>INV-2026-001</span></div><div class="mini-rule"></div><p>Service & repair details</p><div class="mini-rule"></div><p style="text-align:right">Total <strong style="font-size:20px;color:#3d5630">₹ 0</strong></p><p style="margin-top:60px;text-align:center">${esc(s.footer)}</p></div><p class="notice-inline">Use print preview to print directly, or choose “Save as PDF” in your browser.</p></section></div>`}
function field(label,name,value='',type='text',required=false,full=false,extra=''){return `<div class="form-group ${full?'full':''}"><label for="f-${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${required?'required':''} ${extra}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}>`}</div>`}
function selectField(label,name,options,value='',full=false){return `<div class="form-group ${full?'full':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function vehicleFields(v={}){return `${field('Car brand','brand',v.brand||'','text',true,false,'list="brands" autocomplete="off"')}${field('Car model','model',v.model||'','text',true,false,'list="models" autocomplete="off"')}<datalist id="brands">${Object.keys(CARS).map(b=>`<option value="${esc(b)}">`).join('')}</datalist><datalist id="models">${(CARS[v.brand]||[]).map(m=>`<option value="${esc(m)}">`).join('')}</datalist>${field('Registration number','plate',v.plate||'','text',true)}${field('Odometer (km)','odometer',v.odometer||'','number',false,false,'min="0" max="9999999"')}`}
function openModal(title,content,footer='',wide=false,subtitle=''){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-content">${content}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input, .modal select, .modal button')?.focus(),20);}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus();}
function formModal(title,body,submit,wide=false,subtitle=''){openModal(title,`<form id="modal-form" method="post" data-submit="${submit}"><div id="form-error"></div>${body}</form>`,btn('Clear','clear-form','close','','data-form="modal-form"')+btn('Cancel','close')+`<button class="btn primary" type="submit" form="modal-form">${icon('check')}Save in preview</button>`,wide,subtitle)}
function error(text){const el=$('#form-error');if(el){el.className='error';el.textContent=text;}else toast(text)}
function toastLocal(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function phoneKey(value){const digits=String(value||'').replace(/\D/g,'');return digits.length===12&&digits.startsWith('91')?digits.slice(2):digits}
function customerPhoneMatch(value,exceptId=''){const key=phoneKey(value);return key.length>=10?state.customers.find(c=>c.id!==exceptId&&phoneKey(c.phone)===key):null}
function checkCustomerPhone(){const input=$('#f-phone'),notice=$('#customer-phone-check');if(!input||!notice)return;const digits=input.value.replace(/\D/g,'');const match=customerPhoneMatch(input.value,$('#modal-form [name=id]')?.value||'');notice.textContent=match?`Already added: ${match.name} · ${match.brand} ${match.model} (${match.plate}). Open this customer instead.`:digits.length>=10?'No customer found with this number.':'';notice.style.color=match?'#a33d2b':'#386b4c';}
function newCustomer(id){const c=state.customers.find(c=>c.id===id)||{};formModal(id?'Edit customer':'A new connection',`<input type="hidden" name="id" value="${id||''}"><div class="form-grid">${field('Customer name','name',c.name,'text',true)}${field('WhatsApp with country code','phone',c.phone||'91','tel',true,false,'pattern="[0-9+ ()-]{10,20}" placeholder="919876543210"')}<p id="customer-phone-check" class="notice-inline full" role="status" aria-live="polite"></p>${field('Address','address',c.address,'textarea',false,true)}</div><div class="section-label">Vehicle details · type to search or add custom</div><div class="form-grid">${vehicleFields(c)}</div>`,'customer',false,'Basic details for better service and easy updates.');checkCustomerPhone();}
function serviceLine(name='',price='',type='Service'){return `<div class="service-line"><input name="serviceName" placeholder="Service / repair / painting task" value="${esc(name)}" required maxlength="120"><input name="servicePrice" aria-label="Labour charge" type="number" value="${price}" min="0" max="10000000" step=".01" placeholder="₹ charge" required><button type="button" class="iconbtn" data-action="remove-line" aria-label="Remove task">${icon('close')}</button><select name="serviceType" aria-label="Work type" style="grid-column:1/-1;padding:7px;font-size:10px">${['Service','Repair','Painting','Inspection'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></div>`}
function newJob(){const c=state.customers[0]||{};if(!state.customers.length){newCustomer();toast('Add your first customer, then create a job card.');return}if(role==='employer'&&!state.employees.some(e=>e.active!==false)){toast('Add an active employee before creating a job card.');return}formModal('Let’s get this car back on the road.',`<div class="form-grid">${selectField('Customer','customer',state.customers.map(c=>[c.id,`${c.name} · ${c.plate}`]),c.id,true)}${selectField('Assigned to','assigned',state.employees.filter(e=>e.active!==false).map(e=>[e.id,e.name]),role==='employee'?currentEmployee():'')}${field('Expected completion','due',today,'date',true)}</div><div class="section-label">Vehicle · searchable brand and model</div><div class="form-grid">${vehicleFields(c)}${selectField('Fuel type','fuel',['Petrol','Diesel','CNG','Electric','Hybrid','LPG'])}${field('Customer concerns / inspection notes','notes','','textarea',false,true)}</div><div class="section-label">Service, repair & painting tasks</div><div id="service-lines">${serviceLine()}</div>${btn('Add another task','add-service','plus','small')}`,'job',true,'Each task can be updated independently by the assigned employee.');}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id),c=customer(j);if(!j)return;openModal(`#${j.id}`,`<div class="detail-banner">${icon('car')}<div><h2>${esc(j.brand)} ${esc(j.model)}</h2><p>${esc(c.name)} · <span class="plate">${esc(j.plate)}</span></p></div><div style="margin-left:auto">${badge(jobStatus(j))}</div></div><div class="detail-info"><div><small>Assigned to</small>${role==='employer'?`<select id="detail-assigned" data-id="${j.id}" style="padding:7px;font-size:11px">${state.employees.filter(e=>e.active!==false||e.id===j.assigned).map(e=>`<option value="${e.id}" ${e.id===j.assigned?'selected':''}>${esc(e.name)}${e.active===false?' (removed)':''}</option>`).join('')}</select>`:esc(employee(j.assigned).name)}</div><div><small>Odometer / fuel</small>${esc(j.odometer||'—')} km · ${esc(j.fuel)}</div><div><small>Expected completion</small>${j.due}</div></div><div class="info">${esc(j.notes||'No additional concerns recorded.')}</div><div class="section-label">Tasks & progress</div>${j.services.map((s,i)=>`<div class="task"><div><strong>${esc(s.name)}</strong><small>${esc(s.type||'Service')} · Labour ${money(s.price)}</small></div><select class="task-status" data-id="${j.id}" data-index="${i}" aria-label="Status for ${esc(s.name)}">${['Pending','In progress','Finished'].map(v=>`<option ${v===s.status?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<div class="section-label">Parts issued to this job</div>${j.issued.length?j.issued.map(x=>`<div class="task"><strong>${esc(x.name)}</strong><span>${x.qty} × ${money(x.price)}</span></div>`).join(''):'<p class="small muted">No parts issued yet. Use Inventory → Issue to add parts.</p>'}<div class="actions" style="margin-top:23px">${role==='employer'?btn('WhatsApp update','whatsapp','chat','light',`data-id="${j.id}"`):''}${role==='employer'?btn('Create estimate','job-estimate','receipt','',`data-id="${j.id}"`)+btn('Create invoice','job-invoice','receipt','primary',`data-id="${j.id}"`):''}</div>`,btn('Print job card','print-job','print','',`data-id="${j.id}"`)+(session?.admin&&role==='employer'?btn('Delete job card','delete-job','trash','',`data-id="${j.id}"`):'')+btn('Done','close','','primary'),true,'A clear picture of every job, from start to finish.');}
function partForm(id){if(role!=='employer')return;const p=state.inventory.find(p=>p.id===id)||{unit:'piece',min:3};formModal(id?'Update inventory':'Add a spare part',`<input name="id" type="hidden" value="${id||''}"><div class="form-grid">${field('Part name','name',p.name,'text',true,true)}${selectField('Category','category',Object.keys(PART_GROUPS),p.category)}${field('Quantity in stock','stock',p.stock??0,'number',true,false,'min="0" max="1000000" step=".01"')}${field('Price per unit (₹)','price',p.price??0,'number',true,false,'min="0" max="10000000" step=".01"')}${field('Low-stock threshold','min',p.min,'number',true,false,'min="0" max="1000000" step=".01"')}${selectField('Unit','unit',['piece','litre','set','pair','kg','can'],p.unit)}${field('Brand / model compatibility','fitment',p.fitment||'','text',false,true)}</div>`,'part',false,'Employer controls opening stock, restocking and prices.');}
function issuePart(id){const p=state.inventory.find(p=>p.id===id);const jobs=state.jobs.filter(j=>role==='employer'||j.assigned===currentEmployee());if(!jobs.length)return toast('Create an assigned job card before issuing stock.');formModal('Issue stock to a job',`<input type="hidden" name="id" value="${p.id}"><div class="info"><strong>${esc(p.name)}</strong><br>${p.stock} ${p.unit} available · ${money(p.price)} per ${p.unit}</div><div class="form-grid">${selectField('Job card','job',jobs.map(j=>[j.id,`${j.id} · ${j.brand} ${j.model} · ${customer(j).name}`]),'',true)}${field('Quantity to issue','qty',1,'number',true,true,`min="0.01" max="${p.stock}" step=".01"`)}</div><p class="notice-inline">This reduces stock and adds the part to the selected job’s billable items.</p>`,'issue');}
function requestStock(id){const p=state.inventory.find(p=>p.id===id);formModal('Request a part',`<div class="form-grid">${field('Part name','name',p?.name||'','text',true,true)}${field('Quantity needed','qty',1,'number',true,false,'min="1" max="1000000"')}${field('Reason / vehicle details','note','','textarea',false,true)}</div>`,'request',false,'The employer can review and restock requested items.');}
function requestsModal(){openModal('Stock requests',state.requests.map(r=>`<div class="notice-row"><div class="actions" style="justify-content:space-between"><strong>${esc(r.name)} · ${r.qty} requested</strong>${badge(r.status)}</div><p>${esc(employee(r.employee).name)} · ${r.date}<br>${esc(r.note)}</p>${role==='employer'&&r.status!=='Resolved'?`<div class="actions" style="margin-top:12px">${btn('Restock / add item','request-restock','box','small',`data-id="${r.id}"`)}${btn('Mark resolved','request-resolve','check','small',`data-id="${r.id}"`)}</div>`:''}</div>`).join('')||'<div class="empty">No stock requests yet.</div>',btn('Request a part','request-stock','plus','primary'));}
function confirmRemoveEmployee(id){
 if(!session?.admin||role!=='employer')return;
 const e=state.employees.find(x=>x.id===id&&x.active!==false);if(!e)return;
 const jobs=state.jobs.filter(j=>j.assigned===id&&jobStatus(j)!=='Finished').length;
 openModal('Remove employee?',`<p><strong>${esc(e.name)}</strong> will no longer appear in your active team or be able to sign in.</p><p class="notice-inline">Their past jobs and attendance remain. ${jobs?`They have ${jobs} active job${jobs===1?'':'s'} to reassign after removal.`:'They have no active jobs.'}</p>`,btn('Keep employee','close','','light')+btn('Remove employee','confirm-remove-employee','trash','primary',`data-id="${id}"`));
}
function removeEmployee(id){
 if(!session?.admin||role!=='employer')return;
 const e=state.employees.find(x=>x.id===id&&x.active!==false);if(!e)return;
 e.active=false;closeModal();render();toast(`${e.name} removed from the active team.`);
}
function restoreEmployee(id){
 if(!session?.admin||role!=='employer')return;
 const e=state.employees.find(x=>x.id===id&&x.active===false);if(!e)return;
 e.active=true;render();toast(`${e.name} restored to the team.`);
}
function employeeForm(id){if(role!=='employer')return;const e=state.employees.find(e=>e.id===id)||{};formModal(id?'Edit team member':'Add to your team',`<input type="hidden" name="id" value="${id||''}"><div class="form-grid">${field('Full name','name',e.name,'text',true)}${field('Job role','job',e.job,'text',true)}${field('Phone','phone',e.phone,'tel',true)}${field('Email (optional)','email',e.email,'email')}<div class="form-group full"><label for="employee-password">${id?'Set a new password (leave blank to keep existing)':'Set employee password *'}</label><input id="employee-password" name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" ${id?'':'required'} placeholder="At least 8 characters"></div></div><div class="info" style="margin:18px 0 0">The employee’s phone number is their login username. Removed employees cannot sign in; their past jobs and attendance remain.</div>`,'employee');}
function billLine(name='',qty=1,price=0){return `<div class="billing-line"><input name="lineName" aria-label="Item description" value="${esc(name)}" placeholder="Item / service" required><input name="lineQty" aria-label="Quantity" type="number" value="${qty}" min=".01" max="1000000" step=".01" required><input name="linePrice" aria-label="Unit price" type="number" value="${price}" min="0" max="10000000" step=".01" required><button type="button" class="iconbtn" data-action="remove-line" aria-label="Remove line">${icon('close')}</button></div>`}
function billForm(type='Invoice',jobId=''){if(role!=='employer')return;if(!state.jobs.length)return toast('Create a job card first.');const j=state.jobs.find(j=>j.id===jobId)||state.jobs[0];formModal(`Create ${type.toLowerCase()}`,`<input type="hidden" name="type" value="${type}"><div class="form-grid">${selectField('Job card / customer','job',state.jobs.map(j=>[j.id,`${j.id} · ${customer(j).name} · ${j.plate}`]),j.id,true)}${field('Document date','date',today,'date',true)}</div><div class="section-label">Description · quantity · unit price</div><div id="bill-lines">${jobBillLines(j)}</div>${btn('Add line item','add-bill-line','plus','small')}<div class="form-grid" style="margin-top:20px">${field('Discount (₹)','discount',0,'number',true,false,'min="0" step=".01"')}${field('Tax (%)','tax',0,'number',true,false,'min="0" max="100" step=".01"')}</div><div class="billing-total" id="bill-total"></div><p class="notice-inline">Verify prices and your applicable tax before issuing. Shop details and customer details are added automatically.</p>`,'bill',true,'Print directly or save as PDF from the browser print dialog.');updateBillTotal();}
function jobBillLines(j){return j.services.map(s=>billLine(s.name,1,s.price)).join('')+j.issued.map(p=>billLine(p.name,p.qty,p.price)).join('')}
function readBillLines(){return $$('.billing-line').map(r=>({name:$('[name=lineName]',r).value.trim(),qty:Number($('[name=lineQty]',r).value),price:Number($('[name=linePrice]',r).value)}))}
function updateBillTotal(){const el=$('#bill-total');if(!el)return;const i={lines:readBillLines(),discount:Number($('[name=discount]').value),tax:Number($('[name=tax]').value)};el.innerHTML=`Total payable<strong>${money(total(i))}</strong>`}
function documentHeader(type,id,date){const s=state.settings;return `<div class="doc-header"><div>${s.logo?`<img class="doc-logo" src="${s.logo}" alt="Workshop logo">`:''}<h1>${esc(s.name)}</h1><p>${esc(s.address)}<br>Call / WhatsApp: ${esc(s.phone)}${s.gst?`<br>GSTIN: ${esc(s.gst)}`:''}</p></div><div style="text-align:right"><h2>${type.toUpperCase()}</h2><p>${id}<br>Date: ${date}</p></div></div>`}
function billDocument(i){const j=state.jobs.find(j=>j.id===i.job),c=customer(j),subtotal=i.lines.reduce((s,l)=>s+l.qty*l.price,0),taxable=Math.max(0,subtotal-i.discount);return `<article class="document">${documentHeader(i.type,i.id,i.date)}<div class="doc-details"><div><strong>Bill to</strong><br>${esc(c.name)}<br>${esc(c.address)}<br>WhatsApp: +${esc(c.phone)}</div><div><strong>${esc(j.brand)} ${esc(j.model)}</strong><br>Registration: ${esc(j.plate)}<br>Job card: ${j.id}<br>${i.type==='Estimate'?'Estimate — not a payment receipt':`Payment: ${i.status}`}</div></div><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.qty*l.price)}</td></tr>`).join('')}</tbody></table><div class="doc-total"><div><span>Subtotal</span><span>${money(subtotal)}</span></div><div><span>Discount</span><span>− ${money(i.discount)}</span></div><div><span>Tax (${i.tax}%)</span><span>${money(taxable*i.tax/100)}</span></div><div class="grand"><span>Total</span><span>${money(total(i))}</span></div></div><p class="doc-note">${i.type==='Estimate'?'Estimated charges are subject to inspection and customer approval.<br>':''}${esc(state.settings.footer)}</p><div class="doc-sign"><span>Customer signature</span><span>For ${esc(state.settings.name)}<br>Authorized signature</span></div></article>`}
function jobDocument(j){const c=customer(j);return `<article class="document">${documentHeader('Job card',j.id,j.date)}<div class="doc-details"><div><strong>${esc(c.name)}</strong><br>${esc(c.address)}<br>WhatsApp: +${esc(c.phone)}</div><div><strong>${esc(j.brand)} ${esc(j.model)} · ${esc(j.plate)}</strong><br>${esc(j.odometer||'—')} km · ${esc(j.fuel)}<br>Assigned: ${esc(employee(j.assigned).name)}<br>Expected: ${j.due}</div></div><p class="doc-note" style="margin-bottom:20px"><strong>Customer concerns / inspection notes</strong><br>${esc(j.notes||'—')}</p><table><thead><tr><th>Work requested</th><th>Type</th><th>Status</th><th>Labour</th></tr></thead><tbody>${j.services.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.type||'Service')}</td><td>${esc(s.status)}</td><td>${money(s.price)}</td></tr>`).join('')}</tbody></table>${j.issued.length?`<p class="doc-note"><strong>Parts issued:</strong> ${j.issued.map(p=>`${esc(p.name)} × ${p.qty}`).join(', ')}</p>`:''}<p class="doc-note">Vehicle condition / additional inspection notes:<br><br>________________________________________________________________<br><br>________________________________________________________________</p><p class="doc-note">I authorize inspection and the work listed above, subject to agreed charges.</p><div class="doc-sign"><span>Customer approval / signature</span><span>Service advisor / technician</span></div><p class="doc-note">${esc(state.settings.footer)}</p></article>`}
function printDoc(html){$('#print-root').innerHTML=html;window.print()}
function invoicePreview(id){const i=state.invoices.find(i=>i.id===id);openModal(`${i.type} · ${i.id}`,billDocument(i),btn('Print / Save PDF','print-invoice','print','primary',`data-id="${id}"`),true);}
function whatsapp(id){const j=state.jobs.find(j=>j.id===id),c=customer(j);const msg=`Hello ${c.name}, here is an update from ${state.settings.name}.\n\nVehicle: ${j.brand} ${j.model} (${j.plate})\nJob card: ${j.id}\nCurrent status: ${jobStatus(j)}\n${j.services.map(s=>`• ${s.name}: ${s.status}`).join('\n')}\n\nAssigned technician: ${employee(j.assigned).name}\nExpected completion: ${j.due}\nFor any questions, call ${state.settings.phone}.\nThank you!`;openModal('A quick update for your customer',`<div class="info">To ${esc(c.name)} · +${esc(c.phone)}<br>Review the message, then open WhatsApp. You choose when to send.</div><label class="small muted" for="whatsapp-message">Message</label><textarea id="whatsapp-message" style="min-height:280px;margin-top:9px">${esc(msg)}</textarea>`,btn('Clear','clear-message','close')+btn('Cancel','close')+btn('Open WhatsApp','open-whatsapp','chat','primary',`data-id="${id}"`));}
function customerDetail(id){const c=state.customers.find(c=>c.id===id);openModal(esc(c.name),`<div class="detail-banner">${avatar(c.name)}<div><h2>${esc(c.brand)} ${esc(c.model)}</h2><p>${esc(c.plate)}</p></div></div><div class="detail-info"><div><small>WhatsApp</small>+${esc(c.phone)}</div><div style="grid-column:span 2"><small>Address</small>${esc(c.address)}</div></div><div class="section-label">Service history</div>${state.jobs.filter(j=>j.customer===id).map(j=>`<div class="task"><button class="job-id" data-action="job-detail" data-id="${j.id}">${j.id} · ${j.date}</button>${badge(jobStatus(j))}</div>`).join('')||'<p class="small muted">No visits yet.</p>'}`,(session?.admin&&role==='employer'?btn('Delete customer','delete-customer','trash','',`data-id="${id}"`):'')+btn('Edit customer','edit-customer','edit','primary',`data-id="${id}"`));}
function confirmDeleteJob(id){if(!session?.admin||role!=='employer')return;const j=state.jobs.find(j=>j.id===id);if(!j)return;const linked=state.invoices.filter(i=>i.job===id).length;openModal('Delete job card?',`<p>Delete <strong>#${esc(id)}</strong> for ${esc(customer(j).name)}?</p><p class="notice-inline">${linked?`This job has ${linked} invoice or estimate document${linked===1?'':'s'}. Delete is unavailable while those records exist.`:j.issued.length?'This job has issued stock. Delete is unavailable because it would change inventory history.':'This permanently removes the job card and its service history.'}</p>`,btn('Cancel','close')+(!linked&&!j.issued.length?btn('Delete job card','confirm-delete-job','trash','primary',`data-id="${id}"`):''));}
function deleteJob(id){if(!session?.admin||role!=='employer')return;const j=state.jobs.find(j=>j.id===id);if(!j||j.issued.length||state.invoices.some(i=>i.job===id))return;state.jobs=state.jobs.filter(x=>x.id!==id);closeModal();render();toast(`Job card ${id} deleted.`);}
function confirmDeleteCustomer(id){if(!session?.admin||role!=='employer')return;const c=state.customers.find(c=>c.id===id);if(!c)return;const jobs=state.jobs.filter(j=>j.customer===id).length;openModal('Delete customer?',`<p>Delete <strong>${esc(c.name)}</strong>?</p><p class="notice-inline">${jobs?`This customer has ${jobs} job card${jobs===1?'':'s'}. Delete those job cards first.`:'This permanently removes the customer and their contact details.'}</p>`,btn('Cancel','close')+(!jobs?btn('Delete customer','confirm-delete-customer','trash','primary',`data-id="${id}"`):''));}
function deleteCustomer(id){if(!session?.admin||role!=='employer'||state.jobs.some(j=>j.customer===id))return;state.customers=state.customers.filter(c=>c.id!==id);closeModal();render();toast('Customer deleted.');}
function bindSearch(){const inp=$('#search');if(inp)inp.addEventListener('input',()=>{const start=inp.selectionStart;query=inp.value;render();const n=$('#search');n.focus();n.setSelectionRange(start,start)})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'menu':$('.sidebar').classList.toggle('open');$('.mobile-scrim').classList.toggle('show');break;case'nav':page=b.dataset.page;query='';jobFilter='All jobs';render();window.scrollTo(0,0);break;case'logout':logoutRemote();break;case'role':if(!session?.admin)break;role=b.dataset.role;query='';closeModal();render();toast(`${role==='employer'?'Employer':'Employee'} view · Admin preview`);break;case'date':toast(`Showing workshop activity for ${fullDate()}`);break;case'close':closeModal();break;case'new-job':newJob();break;case'new-customer':newCustomer();break;case'edit-customer':newCustomer(id);break;case'customer-detail':customerDetail(id);break;case'delete-customer':confirmDeleteCustomer(id);break;case'confirm-delete-customer':deleteCustomer(id);break;case'delete-job':confirmDeleteJob(id);break;case'confirm-delete-job':deleteJob(id);break;case'new-employee':employeeForm();break;case'edit-employee':employeeForm(id);break;case'remove-employee':confirmRemoveEmployee(id);break;case'confirm-remove-employee':removeEmployee(id);break;case'restore-employee':restoreEmployee(id);break;case'new-part':partForm();break;case'edit-part':partForm(id);break;case'issue-part':issuePart(id);break;case'request-stock':requestStock(id);break;case'requests':requestsModal();break;case'request-restock':{const r=state.requests.find(r=>r.id===id),p=state.inventory.find(p=>p.name.toLowerCase()===r.name.toLowerCase());partForm(p?.id);if(!p)$('[name=name]').value=r.name;break}case'request-resolve':if(role==='employer'){state.requests.find(r=>r.id===id).status='Resolved';render();requestsModal();toast('Request marked resolved in preview.')}break;case'job-detail':jobDetail(id);break;case'job-filter':jobFilter=b.dataset.value;render();break;case'view-grid':view='grid';render();break;case'view-list':view='list';render();break;case'go-jobs':closeModal();page='Job cards';query='';jobFilter='All jobs';render();break;case'go-inventory':closeModal();page='Inventory';query='';render();break;case'go-attendance':closeModal();page='Attendance';query='';render();break;case'add-service':$('#service-lines').insertAdjacentHTML('beforeend',serviceLine());break;case'remove-line':{const line=b.closest('.service-line,.billing-line');if(line.parentElement.children.length>1){line.remove();updateBillTotal()}else toast('Keep at least one line item.');break}case'new-invoice':billForm('Invoice');break;case'new-estimate':billForm('Estimate');break;case'job-invoice':billForm('Invoice',id);break;case'job-estimate':billForm('Estimate',id);break;case'add-bill-line':$('#bill-lines').insertAdjacentHTML('beforeend',billLine());updateBillTotal();break;case'invoice-preview':invoicePreview(id);break;case'mark-paid':if(role==='employer'){Object.assign(state.invoices.find(i=>i.id===id),{status:'Paid',paidDate:today});render();toast('Marked paid. Dashboard sales updated.')}break;case'convert-invoice':{if(role!=='employer')break;const old=state.invoices.find(i=>i.id===id),i={...structuredClone(old),id:nextDocId('Invoice'),type:'Invoice',status:'Unpaid',date:today};state.invoices.push(i);render();invoicePreview(i.id);break}case'print-invoice':printDoc(billDocument(state.invoices.find(i=>i.id===id)));break;case'print-job':printDoc(jobDocument(state.jobs.find(j=>j.id===id)));break;case'whatsapp':whatsapp(id);break;case'open-whatsapp':{const c=customer(state.jobs.find(j=>j.id===id)),phone=c.phone.replace(/\D/g,'');if(!/^\d{10,15}$/.test(phone)){toast('Add a valid WhatsApp number including country code.');break}window.open(`https://wa.me/${phone}?text=${encodeURIComponent($('#whatsapp-message').value)}`,'_blank','noopener,noreferrer');toast('WhatsApp opened with your message. Send it there.');break}case'clock':requestCheckinOrCheckout();break;case'add-attendance':addAttendance();break;case'brand':{const brand=b.dataset.brand;openModal(esc(brand),`<p class="small muted" style="margin-bottom:18px">Current and historical Indian-market model suggestions.</p><div class="models">${CARS[brand].map(m=>`<span>${esc(m)}</span>`).join('')}</div>`,btn('Done','close','','primary'));break}case'save-settings':saveSettings();break;case'notifications':openModal('Your workshop updates',`${role==='employer'?approvalBanner():''}<div class="notice-row"><strong>${state.jobs.filter(j=>jobStatus(j)==='Finished').length} vehicles ready for delivery</strong><p>Open a finished job card to prepare an invoice and send the customer a WhatsApp update.</p>${txtbtn('View job cards','go-jobs')}</div><div class="notice-row"><strong>${state.requests.filter(r=>r.status==='Requested').length} stock requests pending</strong><p>Review requests from your team and update inventory.</p>${txtbtn('Review requests','requests')}</div>`,btn('Done','close','','primary'));break;}}
);
document.addEventListener('input',e=>{if(e.target.id==='f-phone'&&$('#modal-form')?.dataset.submit==='customer')checkCustomerPhone();});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='category'){category=el.value;render()}if(el.id==='chart-range'){chartRange=el.value;render()}if(el.name==='brand'){const modelInput=$('[name=model]');if(modelInput)modelInput.value='';const models=$('#models');if(models)models.innerHTML=(CARS[el.value]||[]).map(m=>`<option value="${esc(m)}">`).join('');}if(el.name==='customer'&&el.value&&$('#modal-form')?.dataset.submit==='job'){const c=state.customers.find(c=>c.id===el.value);['brand','model','plate'].forEach(k=>$(`[name=${k}]`).value=c[k]);$('#models').innerHTML=(CARS[c.brand]||[]).map(m=>`<option value="${esc(m)}">`).join('')}if(el.name==='job'&&el.value&&$('#bill-lines')){$('#bill-lines').innerHTML=jobBillLines(state.jobs.find(j=>j.id===el.value));updateBillTotal()}if(el.classList.contains('task-status')){const j=state.jobs.find(j=>j.id===el.dataset.id);j.services[Number(el.dataset.index)].status=el.value;render();jobDetail(j.id);toast('Task status updated in preview.')}if(el.id==='detail-assigned'){state.jobs.find(j=>j.id===el.dataset.id).assigned=el.value;render();toast('Assignment updated in preview.')}if(el.id==='logo-file')loadLogo(el.files[0]);});
document.addEventListener('input',e=>{if(e.target.closest('#modal-form')&&$('#bill-total'))updateBillTotal()});
function nextDocId(type){const prefix=type==='Invoice'?'INV':'EST';return `${prefix}-${new Date().getFullYear()}-${String(state.invoices.filter(i=>i.type===type).length+1).padStart(3,'0')}`}
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')==='admin-profile-form'){e.preventDefault();saveAdminProfile();return;}if(e.target.getAttribute('id')==='settings-form'){e.preventDefault();saveSettings();return;}if(e.target.getAttribute('id')==='login-form'){e.preventDefault();await login(e.target);return;}if(e.target.getAttribute('id')!=='modal-form')return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));for(const [k,v]of Object.entries(d))if(typeof v==='string'&&k!=='password')d[k]=v.trim();const kind=f.dataset.submit;try{switch(kind){case'customer':{const phone=d.phone.replace(/\D/g,'');if(!/^\d{10,15}$/.test(phone))return error('Enter a WhatsApp number with country code (10–15 digits).');const duplicate=customerPhoneMatch(phone,d.id);if(duplicate)return error(`This number already belongs to ${duplicate.name}. Open that customer instead.`);const record={id:d.id||`c${Date.now()}`,name:d.name,phone,address:d.address,brand:d.brand,model:d.model,plate:d.plate.toUpperCase()};if(!d.name||!d.brand||!d.model||!d.plate)return error('Name, brand, model and registration are required.');const old=state.customers.find(c=>c.id===d.id);if(old)Object.assign(old,record);else state.customers.push(record);break}case'job':{if(!state.customers.some(c=>c.id===d.customer)||!state.employees.some(e=>e.id===(role==='employee'?currentEmployee():d.assigned)))return error('Choose a customer and employee.');const services=$$('.service-line').map(r=>({name:$('[name=serviceName]',r).value.trim(),price:Number($('[name=servicePrice]',r).value),type:$('[name=serviceType]',r).value,status:'Pending'}));if(!services.length||services.some(s=>!s.name||!Number.isFinite(s.price)||s.price<0))return error('Add at least one task with a valid charge.');state.jobs.unshift({id:`JC-${Math.max(...state.jobs.map(j=>Number(j.id.split('-')[1])),1040)+1}`,customer:d.customer,assigned:role==='employee'?currentEmployee():d.assigned,date:today,due:d.due,brand:d.brand,model:d.model,plate:d.plate.toUpperCase(),odometer:Number(d.odometer)||0,fuel:d.fuel,notes:d.notes,services,issued:[]});page='Job cards';query='';jobFilter='All jobs';break}case'part':{if(role!=='employer')return;if(!d.category||!d.unit)return error('Choose a category and unit.');const record={name:d.name,category:d.category,stock:Number(d.stock),price:Number(d.price),min:Number(d.min),unit:d.unit,fitment:d.fitment||'Confirm vehicle compatibility',configured:true};if(!record.name||[record.stock,record.price,record.min].some(n=>!Number.isFinite(n)||n<0))return error('Enter a part name and valid non-negative amounts.');const old=state.inventory.find(p=>p.id===d.id);if(old)Object.assign(old,record);else state.inventory.unshift({...record,id:`P-${state.inventory.length+1}`});break}case'issue':{const p=state.inventory.find(p=>p.id===d.id),j=state.jobs.find(j=>j.id===d.job),qty=Number(d.qty);if(!j||!p)return error('Choose a valid job and part.');if(!Number.isFinite(qty)||qty<=0||qty>p.stock)return error('Quantity must be greater than zero and within available stock.');p.stock=Math.round((p.stock-qty)*100)/100;j.issued.push({name:p.name,qty,price:p.price,part:p.id});break}case'request':if(!d.name)return error('Enter the requested part name.');state.requests.unshift({id:`R-${Date.now()}`,name:d.name,qty:Number(d.qty),note:d.note,employee:currentEmployee(),date:today,status:'Requested'});break;case'employee':{if(role!=='employer')return;const old=state.employees.find(x=>x.id===d.id);const phone=d.phone.replace(/\D/g,'');if(!/^\d{10,15}$/.test(phone))return error('Enter a valid phone number (10–15 digits).');if(state.employees.some(e=>e.phone===phone&&e.id!==d.id))return error('This phone number is already used by another employee.');if(!old&&!d.password)return error('Set a password for the employee.');if(d.password&&d.password.length<8)return error('Use at least 8 characters for the password.');const record={id:d.id||`e${Date.now()}`,name:d.name,job:d.job,email:d.email,phone,passwordHash:d.password?await hashPassword(d.password):old?.passwordHash};if(old)Object.assign(old,record);else state.employees.push(record);break}case'attendance':{if(!saveAttendanceForm(d))return;break}case'bill':{if(role!=='employer')return;if(!state.jobs.some(j=>j.id===d.job))return error('Choose a job card.');const lines=readBillLines();if(lines.some(l=>!l.name||!Number.isFinite(l.qty)||l.qty<=0||!Number.isFinite(l.price)||l.price<0))return error('Every line needs a description, positive quantity and valid price.');const subtotal=lines.reduce((s,l)=>s+l.qty*l.price,0);if(Number(d.discount)>subtotal)return error('Discount cannot exceed the subtotal.');const i={id:nextDocId(d.type),job:d.job,type:d.type,date:d.date,status:d.type==='Estimate'?'Estimate':'Unpaid',lines,discount:Number(d.discount),tax:Number(d.tax)};state.invoices.push(i);closeModal();page='Invoices & estimates';render();invoicePreview(i.id);toast(`${d.type} created in preview.`);return}}
closeModal();render();toast('Updated in this preview. Changes reset on refresh.');}catch(err){error('Please check the entered details and try again.');console.error(err)}});
let pendingLogo=null;
function loadLogo(file){if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024)return toast('Choose a PNG or JPG under 2 MB.');const reader=new FileReader();reader.onload=()=>{pendingLogo=reader.result;$('#logo-preview').innerHTML=`<img src="${reader.result}" alt="Uploaded logo preview">`};reader.readAsDataURL(file)}
function saveSettings(){if(role!=='employer')return;const f=$('#settings-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(!d.name.trim()||!d.phone.trim()||!d.address.trim())return toast('Add your shop name, phone and address.');Object.assign(state.settings,d);if(pendingLogo!==null){state.settings.logo=pendingLogo;pendingLogo=null}render();toast('Shop details updated for this preview’s documents.');}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusables=$$('button,input,select,textarea,a[href]', $('.modal')).filter(el=>!el.disabled&&el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function currentEmployee(){return session?.employee||'e1'}
async function hashPassword(value){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(bytes)).map(b=>b.toString(16).padStart(2,'0')).join('')}
